import{_ as a,o as e,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"💡 学习建议","description":"先跑通再优化:第 2 步的最小 demo 跑通之前,不要提前看第 5 步的完整 Chain","frontmatter":{},"headers":[],"relativePath":"agent/学习计划/项目A-知识库问答/13-study-tips.md","filePath":"agent/学习计划/项目A-知识库问答/13-study-tips.md","lastUpdated":1793930980000}'),r={name:"agent/学习计划/项目A-知识库问答/13-study-tips.md"};function n(s,t,l,d,g,_){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="💡-学习建议" tabindex="-1">💡 学习建议 <a class="header-anchor" href="#💡-学习建议" aria-label="Permalink to &quot;💡 学习建议&quot;">​</a></h1><ol><li><strong>先跑通再优化</strong>:第 2 步的最小 demo 跑通之前,不要提前看第 5 步的完整 Chain</li><li><strong>分块策略要多试</strong>:同一份文档用固定长度 / 按段落 / 按标题切,召回效果差别很大,做一次对比再定</li><li><strong>Embedding 换模型要重算索引</strong>:换模型后旧向量失效,这是最常见的坑</li><li><strong>流式输出要单独调</strong>:SSE 断了要能重连,别等联调时才发现</li><li>完成后回 <a href="/agent/学习计划/9-学习进度跟踪">进度跟踪页</a> 打卡</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>核心建议:<strong>先跑通再优化、先评估再调参、先做出丑但能用的版本</strong>。</li><li>每步留一个「<strong>我学到的一个坑</strong>」的笔记,面试时这些具体细节比概念更有说服力。</li><li>卡住超过 2 小时就换资源或拆小问题,不要死磕。</li><li>建议把项目<strong>部署一次</strong>(哪怕免费额度),部署过程能暴露大量本地看不出的工程问题。</li><li>完成后做一次「<strong>三分钟演示录像</strong>」,用来复盘和面试展示。</li><li>面试加分:能讲「<strong>我把这个项目部署到了线上并做了 30 条评测</strong>」,这是完整的工程闭环。</li></ul>',4)])])}const h=a(r,[["render",n]]);export{p as __pageData,h as default};
